type Shape =
  | { kind: 'circle'; radius: number }
  | { kind: 'rect'; width: number; height: number }
  | { kind: 'square'; side: number };

function assertNever(x: never): never {
  throw new Error('Unhandled variant: ' + JSON.stringify(x));
}

function area(s: Shape): number {
  switch (s.kind) {
    case 'circle':
      return Math.PI * s.radius ** 2;   // s narrowed to circle
    case 'rect':
      return s.width * s.height;
    case 'square':
      return s.side ** 2;
    default:
      // If a new variant is added to Shape, 's' is no longer 'never'
      // here and this line fails to compile - exhaustiveness enforced.
      return assertNever(s);
  }
}

area({ kind: 'circle', radius: 2 });

interface Cat { meow(): void; }
interface Dog { bark(): void; }
type Animal = Cat | Dog;

// Type predicate: 'animal is Cat' enables narrowing
function isCat(animal: Animal): animal is Cat {
  return 'meow' in animal;
}

function speak(a: Animal) {
  if (isCat(a)) {
    a.meow(); // a narrowed to Cat
  } else {
    a.bark(); // a narrowed to Dog
  }
}

