function pad(value: string | number) {
  if (typeof value === 'number') return ' '.repeat(value); // number
  return value.trim();                                     // string
}

// Assertion function variant
function assertIsCat(a: Animal): asserts a is Cat {
  if (!('meow' in a)) throw new Error('not a cat');
}

