// Return type depends on the input type -> overloads shine here
function reverse(value: string): string;
function reverse<T>(value: T[]): T[];
function reverse(value: string | unknown[]): string | unknown[] {
  // implementation signature - NOT visible to callers
  if (typeof value === 'string') return value.split('').reverse().join('');
  return [...value].reverse();
}

const s = reverse('abc'); // type: string
const a = reverse([1, 2, 3]); // type: number[]

